use vstd::prelude::*;

verus! {

fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (out_a: Vec<i8>, out_b: Vec<i8>)
    requires
        a.len() > 0,
        b.len() > 0,
        // lengths must match or one of them must be 1
        a.len() == b.len() || a.len() == 1 || b.len() == 1,
    ensures
        // both outputs have length equal to the maximum of the input lengths
        let len = a.len().max(b.len());
        out_a.len() == len,
        out_b.len() == len,
        // for each index, if the original vector had full length then we reuse its element,
        // otherwise (it had length 1) we repeat its sole element
        forall |i: usize| i < len ==>
            out_a[i] == if a.len() == len { a[i] } else { a[0] },
        forall |i: usize| i < len ==>
            out_b[i] == if b.len() == len { b[i] } else { b[0] },
{
    let m = a.len();
    let n = b.len();
    debug_assert!(m > 0 && n > 0 && (m == n || m == 1 || n == 1));

    let len = m.max(n);

    let out_a = if m == len {
        a
    } else {
        vec![a[0]; len]
    };

    let out_b = if n == len {
        b
    } else {
        vec![b[0]; len]
    };

    (out_a, out_b)
}

} // verus!

